import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 38 Everything except the weather","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 38 Everything except the weather","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 37 The Olympic Games","link":"/life/english/new-concept/book-2/unit-02/lesson-037"},"next":{"text":"第二册：实践与进步 · Lesson 39 Am I all right?","link":"/life/english/new-concept/book-2/unit-02/lesson-039"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 37 The Olympic Games","link":"/life/english/new-concept/book-2/unit-02/lesson-037"},"next":{"text":"第二册：实践与进步 · Lesson 39 Am I all right?","link":"/life/english/new-concept/book-2/unit-02/lesson-039"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-038.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-038.md"}'),r={name:"life/english/new-concept/book-2/unit-02/lesson-038.md"};function i(l,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-38-everything-except-the-weather" tabindex="-1">第二册：实践与进步 · Lesson 38 Everything except the weather <a class="header-anchor" href="#第二册-实践与进步-·-lesson-38-everything-except-the-weather" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 38 Everything except the weather&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>退休后搬到理想地点，却发现天气与预期不同；练习长时间愿望与搬家前的准备。本课的语言观察是：had dreamed for years 描述搬家前已经持续多年的愿望；moved 才是叙事的主时间点。for years 不会自动要求现在完成时。完成学习后，请写一个理想生活与现实差异的小段落，最后给出调整办法。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>weather</td><td>/ˈweðə/</td><td>n.</td><td>天气</td><td>changeable weather</td></tr><tr><td>retire</td><td>/rɪˈtaɪə/</td><td>v.</td><td>退休</td><td>retire early</td></tr><tr><td>settle</td><td>/ˈsetəl/</td><td>v.</td><td>定居</td><td>settle abroad</td></tr><tr><td>dream</td><td>/driːm/</td><td>n.</td><td>梦想；梦</td><td>a childhood dream</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>dream of — 梦想、向往，可接动名词</li><li>except for — 除了某个局部因素，用于说明例外</li></ul><h2 id="语法讲解-过去完成时与先后关系" tabindex="-1">语法讲解：过去完成时与先后关系 <a class="header-anchor" href="#语法讲解-过去完成时与先后关系" aria-label="Permalink to &quot;语法讲解：过去完成时与先后关系&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had dreamed for years 描述搬家前已经持续多年的愿望；moved 才是叙事的主时间点。for years 不会自动要求现在完成时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Before he moved north, Joel had dreamed of a quiet village.</p></blockquote><p>搬到北方之前，乔尔曾向往一个安静的村庄。</p><p>Before 从句 moved 给出过去参照，had dreamed 回顾更早的愿望；dream of 后接名词短语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>dream of live 错误，介词 of 后若接动词应为 living。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 peaceful 后停顿，重读 but 与 long，突出天气带来的转折。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Before he moved north, Joel had dreamed of a quiet village. The village was peaceful, but the winters were long. He bought warmer clothes instead of moving again.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个理想生活与现实差异的小段落，最后给出调整办法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Before 从句 moved 给出过去参照，had dreamed 回顾更早的愿望；dream of 后接名词短语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：dream of live 错误，介词 of 后若接动词应为 living。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填介词：He dreamed ___ living in a village.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> of</p><p><strong>解析：</strong> dream of 是固定搭配，of 后接动名词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>他选择搬走还是买更暖的衣服？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He bought warmer clothes.</p><p><strong>解析：</strong> instead of moving again 明确排除了再次搬家。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>选择：Before he moved, he has dreamed / had dreamed of village life.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He had dreamed of village life.</p><p><strong>解析：</strong> 叙事参照点在过去，早于该点使用过去完成时。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时与先后关系。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-037">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-039">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(r,[["render",i]]);export{u as __pageData,f as default};
